insert into public.products (id, organization_id, name, description, category, audience, outcome, tags, owners, maturity, source_url, support_url, story, license_attested, submitted_by, owner_confirmed_at, validated_at)
select '33333333-3333-4333-8333-100000000007', '11111111-1111-1111-1111-111111111111', 'Multi-Agent Custom Automation Engine', 'Teams of AI agents that plan, carry out and check multi-step business tasks on Microsoft Foundry. A planner drafts the plan, a person approves it, and specialized agents do the work.', 'Operations & AI', 'Operations, engineering and back-office teams with multi-step, cross-team processes', 'Cross-team tasks planned and executed by AI agents, with a person approving every plan', '{foundry,agents,agent-framework,automation}'::text[], '[{"name":"Microsoft","email":"","role":"Product team","team":"github.com/microsoft"}]'::jsonb, 'featured', 'https://github.com/microsoft/Multi-Agent-Custom-Automation-Engine-Solution-Accelerator', null, '{"source":"Project README and diagrams","overview":["When dealing with complex organizational tasks, people face coordinating across departments, keeping processes consistent and using resources well. This accelerator lets a user describe a task and have it processed by a group of AI agents, each specialized in a different part of the business.","It runs on Microsoft Foundry and Agent Framework: a planner builds the plan from a team of agents, a person reviews it, and the agents carry it out step by step. Teams ship for contract review, RFP review, content generation and more, and new teams are configured rather than coded. In oil and gas that maps to work such as contract and procurement review, or packaging work for a maintenance turnaround."],"benefits":[{"title":"People focus on what matters","body":"The agents do the heavy lifting of coordinating activities across the organization, so people spend their time on their specialisms."},{"title":"Generative AI that scales","body":"One capability unlocks many use cases, without building one application after another."},{"title":"Efficient, checked automation","body":"Analysing, planning and executing complex tasks takes less time, and multi-agent validation keeps the result accurate."}],"steps":[{"title":"A person describes the task","body":"Users work in the web app on App Service, describing what they need in plain language.","services":["app-service"]},{"title":"The planner drafts a plan","body":"The API on Container Apps runs Agent Framework''s Magentic orchestration: the planner picks a team of specialized agents and drafts a step-by-step plan.","services":["container-apps"]},{"title":"A person approves it","body":"Human in the loop: the plan is shown for review before anything runs.","services":[]},{"title":"Agents do the work","body":"The group chat manager runs the plan step by step. Each agent (for example triage, research or compliance) runs on Foundry Agent Service with Foundry models (GPT-4.1 and o4).","services":["ai-foundry"]},{"title":"Grounded in your data and tools","body":"Agents retrieve knowledge through Azure AI Search over documents in Storage and Foundry IQ, and call tools through an MCP server on Container Apps.","services":["ai-search","storage"]},{"title":"Every plan is kept","body":"Cosmos DB stores current and past plans, steps and results. Container Registry holds the web and API images, built automatically from the source.","services":["cosmos","container-registry"]}],"diagrams":[{"title":"Solution architecture","url":"https://raw.githubusercontent.com/microsoft/Multi-Agent-Custom-Automation-Engine-Solution-Accelerator/9ac63ab2f1b018eec66198f7c01e2c27992671a9/docs/images/readme/architecture.png"},{"title":"How the agents work","url":"https://raw.githubusercontent.com/microsoft/Multi-Agent-Custom-Automation-Engine-Solution-Accelerator/9ac63ab2f1b018eec66198f7c01e2c27992671a9/docs/images/readme/agent_flow.png","caption":"The Magentic planner builds a plan from teams of agents, a person approves it, and the group chat manager runs it."}],"scenario":{"title":"Business scenario","body":"Companies maintaining and modernizing their business processes often struggle to coordinate complex tasks across departments. With this accelerator those processes are automated, and every task is coordinated and executed consistently.","points":["Coordinating activities across different departments","Time-consuming manual management of complex workflows","Errors from manual coordination","Too few people to meet growing automation demand"]},"deploy":{"command":"azd up","guide":"https://github.com/microsoft/Multi-Agent-Custom-Automation-Engine-Solution-Accelerator/blob/9ac63ab2f1b018eec66198f7c01e2c27992671a9/docs/DeploymentGuide.md","prerequisites":["Azure Developer CLI 1.18.0 or later","Permission to create resource groups and resources","Foundry model quota in a supported region"]}}'::jsonb, false, 'Cloud Delivery catalog', now(), now()
