select '33333333-3333-4333-8333-100000000008', '11111111-1111-1111-1111-111111111111', 'Real-Time Intelligence for Operations', 'Live and historical equipment telemetry in Microsoft Fabric: a real-time operations dashboard, anomaly detection with email alerts, and a data agent that answers questions about how assets are running.', 'Data & Real-Time Intelligence', 'Operations, reliability and maintenance teams', 'Equipment problems spotted as they happen, and answers about operations in plain language', '{fabric,real-time-intelligence,telemetry,anomaly-detection}'::text[], '[{"name":"Microsoft","email":"","role":"Product team","team":"github.com/microsoft"}]'::jsonb, 'validated', 'https://github.com/microsoft/real-time-intelligence-operations-solution-accelerator', null, '{"source":"Project README and architecture diagram","overview":["A complete real-time intelligence platform on Microsoft Fabric: it analyzes live and historical telemetry through interactive dashboards, detects anomalies and sends alerts, and includes an AI data agent for conversational insights.","In oil and gas, connect compressor, pump and pipeline telemetry, or well-pad SCADA, to Event Hubs in place of the simulator. The dashboard tiles, anomaly rules and agent instructions are where you make it yours."],"benefits":[{"title":"A live view of every asset","body":"A Real-Time Intelligence dashboard shows how assets are performing and individual sensor trends, from Eventhouse."},{"title":"Anomalies raise the alarm","body":"Activator watches the stream with anomaly-detection rules and emails the team when one fires."},{"title":"Ask your telemetry questions","body":"A Fabric Data Agent answers live operational questions in plain language."}],"steps":[{"title":"Telemetry streams in","body":"A simulator loads 90 days of history and then streams live events into Azure Event Hubs. Your own sources connect here.","services":["event-hubs"]},{"title":"Fabric ingests it","body":"Fabric Eventstream takes the stream into Eventhouse, a KQL database on OneLake.","services":["fabric"]},{"title":"Dashboards update live","body":"The Real-Time Dashboard queries Eventhouse for asset performance and sensor trends.","services":[]},{"title":"Anomalies send alerts","body":"Activator applies anomaly-detection rules to the stream and sends an email alert when one fires.","services":[]},{"title":"Ask in plain language","body":"A Fabric Data Agent answers questions over the telemetry in Eventhouse.","services":[]}],"diagrams":[{"title":"Architecture","url":"https://raw.githubusercontent.com/microsoft/real-time-intelligence-operations-solution-accelerator/d2f8e7684de02f81182218ab6da41e23c5bda1de/docs/images/readme/solution-architecture.png"}],"deploy":{"command":"azd up","guide":"https://github.com/microsoft/real-time-intelligence-operations-solution-accelerator/blob/d2f8e7684de02f81182218ab6da41e23c5bda1de/docs/DeploymentGuide.md","prerequisites":["Microsoft Fabric enabled in the tenant","Azure Developer CLI and Azure CLI, both signed in"]}}'::jsonb, false, 'Cloud Delivery catalog', now(), now()
