select '33333333-3333-4333-8333-100000000009', '11111111-1111-1111-1111-111111111111', 'Content Processing', 'Extracts structured data from documents (text, images, tables and forms) with Azure AI Content Understanding and Azure OpenAI, maps it to your schemas with confidence scores, and summarizes and gap-checks multi-document cases.', 'Operations & AI', 'Operations and engineering teams that process document-heavy cases', 'Documents turned into validated, structured data, with people reviewing only what''s uncertain', '{foundry,content-understanding,documents,agent-framework}'::text[], '[{"name":"Microsoft","email":"","role":"Product team","team":"github.com/microsoft"}]'::jsonb, 'validated', 'https://github.com/microsoft/content-processing-solution-accelerator', null, '{"source":"Project README and architecture diagram","overview":["The content processing engine handles text, images, tables and graphs with schema-based transformation and confidence scoring. Each document runs through a four-stage pipeline (extract, map, evaluate, save), and a workflow summarizes and gap-checks every document in a case.","In oil and gas, point it at inspection reports, permits, run tickets or equipment datasheets: define a schema and it extracts the fields with a confidence score for each, so people review only what''s uncertain."],"benefits":[{"title":"Extraction you can trust","body":"Every extraction and schema mapping is scored for accuracy, so the uncertain ones are flagged for human validation."},{"title":"Whole cases, not single files","body":"Upload many documents to one case; the workflow summarizes them and finds gaps across all of them."},{"title":"Your schemas","body":"Schemas define what to extract, so the same engine serves new document types without new code."}],"steps":[{"title":"Upload the documents","body":"Users upload files to a case through the web UI, or call the API; both run on Container Apps.","services":["container-apps"]},{"title":"Queued for processing","body":"The API queues the work on Storage queues and the content processor picks it up.","services":["storage"]},{"title":"Extract and map","body":"Azure AI Content Understanding extracts text, tables and images; Azure OpenAI maps them to your schema with confidence scores.","services":["ai-foundry"]},{"title":"Summarize and find gaps","body":"An Agent Framework workflow summarizes the whole case and finds what''s missing across its documents.","services":[]},{"title":"Results are kept","body":"Results go to Blob storage, and task status and history to Cosmos DB; App Configuration and Container Registry support the apps.","services":["cosmos","app-configuration","container-registry"]}],"diagrams":[{"title":"Architecture","url":"https://raw.githubusercontent.com/microsoft/content-processing-solution-accelerator/cea554849ebc9580d354f88ba274c0f8d267a14f/docs/images/readme/solution-architecture.png"}],"deploy":{"command":"azd up","guide":"https://github.com/microsoft/content-processing-solution-accelerator/blob/cea554849ebc9580d354f88ba274c0f8d267a14f/docs/DeploymentGuide.md"}}'::jsonb, false, 'Cloud Delivery catalog', now(), now()
