-- Chat with Your Data: https://github.com/Azure-Samples/chat-with-your-data-solution-accelerator @ f3b4e920e293
insert into public.products (id, organization_id, name, description, category, audience, outcome, tags, owners, maturity, source_url, support_url, story, license_attested, submitted_by, owner_confirmed_at, validated_at)
select '33333333-3333-4333-8333-100000000011', '11111111-1111-1111-1111-111111111111', 'Chat with Your Data', 'A conversational assistant grounded in your own documents, answering with inline citations back to the source, with an ingestion pipeline, content safety and voice input.', 'Operations & AI', 'Field, engineering and HSE staff who need answers from manuals, standards and procedures', 'Grounded answers from your documents, with the source cited', '{foundry,rag,search,assistant}'::text[], '[{"name":"Microsoft","email":"","role":"Product team","team":"github.com/Azure-Samples"}]'::jsonb, 'validated', 'https://github.com/Azure-Samples/chat-with-your-data-solution-accelerator', null, '{"source":"Project README","overview":["Organizations hold vast unstructured knowledge in contracts, policies and product manuals that is hard to search. Chat with Your Data indexes that content and puts a natural-language chat in front of it, with answers cited back to the source.","In oil and gas, that''s operating procedures, OEM manuals, engineering standards and HSE procedures, answered at the point of work."],"benefits":[{"title":"Answers you can check","body":"Responses are grounded in your indexed content, with inline citations back to the source documents."},{"title":"Bring your documents","body":"Upload files or index web pages; the pipeline parses, chunks and embeds many file types."},{"title":"No secrets to manage","body":"One user-assigned managed identity and Azure RBAC authorize every call: no Key Vault, no application secrets."}],"steps":[{"title":"Documents are ingested","body":"Uploaded documents or web pages land in Storage; a queue triggers the ingestion worker, which parses, chunks and embeds them into the index.","services":["storage","functions"]},{"title":"A user asks","body":"People chat in a React app on Container Apps, by typing or by voice.","services":["container-apps"]},{"title":"Retrieve and ground","body":"The backend retrieves the most relevant passages from AI Search (or PostgreSQL with pgvector) and grounds a Foundry model on them.","services":["ai-search","ai-foundry"]},{"title":"Safe, cited answers","body":"Content Safety screens prompts and responses, the answer streams back with citations, and chat history is kept in Cosmos DB or PostgreSQL.","services":["cosmos"]},{"title":"One identity","body":"A single user-assigned managed identity with RBAC authorizes every downstream call.","services":["managed-identity"]}],"deploy":{"command":"azd up"},"diagrams":[]}'::jsonb, false, 'Cloud Delivery catalog', now(), now()
