insert into public.products (id, organization_id, name, description, category, audience, outcome, tags, owners, maturity, source_url, support_url, story, license_attested, submitted_by, owner_confirmed_at, validated_at)
select '33333333-3333-4333-8333-100000000001', '11111111-1111-1111-1111-111111111111', 'OSDU Developer Platform', 'A personal OSDU data platform on AKS for building and testing subsurface applications against well, wellbore, log and seismic data. Cosmos DB, Storage and Key Vault sit behind private endpoints, and Flux deploys the OSDU services.', 'Upstream & Resources', 'Subsurface application developers and energy data platform teams', 'A working OSDU instance to build against, without a full Data Manager for Energy rollout', '{osdu,subsurface,aks,gitops}'::text[], '[{"name":"Microsoft","email":"","role":"Product team","team":"github.com/Azure"}]'::jsonb, 'validated', 'https://github.com/Azure/osdu-developer', 'https://azure.github.io/osdu-developer/', '{"source":"Project README and architecture diagram","overview":["OSDU is the open standard for subsurface and well data. This is a developer-tier OSDU you own end to end, for building and testing applications against real OSDU APIs without waiting for a full Azure Data Manager for Energy rollout.","Deploy it with the Azure Developer CLI from a Codespace or your machine. From then on Flux keeps the cluster in step with Git, so the components and applications you add are versioned like code."],"benefits":[{"title":"Real OSDU in your own subscription","body":"The same OSDU services and APIs your applications will use in production, on infrastructure you control."},{"title":"GitOps from day one","body":"Flux installs OSDU components and applications from Git, so every change is reviewed and repeatable."},{"title":"Production-like resilience","body":"Node pools spread across three availability zones, with the data services kept private to the cluster''s network."}],"steps":[{"title":"Deploy from Git","body":"An engineer deploys with azd from a Codespace or locally. Flux GitOps then installs the OSDU components and applications into AKS from the Git repository.","services":["aks"]},{"title":"Users reach OSDU","body":"External users come in through a public IP and the external load balancer; internal users through an internal load balancer.","services":["network-spoke"]},{"title":"AKS runs the services","body":"OSDU services run on AKS across a default pool, an internal pool and three zoned pools, one per availability zone, with autoscale and Azure Policy.","services":["aks"]},{"title":"Managed services hold the data","body":"Storage accounts, Cosmos DB, Service Bus, Key Vault and Azure Cache for Redis hold OSDU data, messages, secrets and cache, reached from the cluster''s virtual network.","services":["storage","cosmos","key-vault","private-endpoints"]},{"title":"Configured and observed","body":"App Configuration holds the settings and Container Registry the images; Log Analytics and Application Insights collect logs and traces.","services":["app-configuration","monitoring"]}],"diagrams":[{"title":"Architecture","url":"https://raw.githubusercontent.com/Azure/osdu-developer/ab994b273013cb49a744179b7d368f21528317ee/docs/src/images/architecture.png"}],"deploy":{"command":"azd up","guide":"https://azure.github.io/osdu-developer/","prerequisites":["Azure Developer CLI","The AKS preview features listed in the README, registered in the subscription"]}}'::jsonb, false, 'Cloud Delivery catalog', now(), now()
