select '33333333-3333-4333-8333-100000000002', '11111111-1111-1111-1111-111111111111', 'ADME Experience Lab', 'Creates an Azure Data Manager for Energy developer-tier instance loaded with the TNO open well and wellbore dataset, with a web portal and Power BI reports to explore it. Built for demos, training and evaluation.', 'Upstream & Resources', 'Energy data teams evaluating Azure Data Manager for Energy', 'A loaded Data Manager for Energy instance to evaluate with real well data', '{adme,osdu,tno,training}'::text[], '[{"name":"Microsoft","email":"","role":"Product team","team":"github.com/microsoft"}]'::jsonb, 'validated', 'https://github.com/microsoft/azure-data-manager-for-energy-experience-lab', null, '{"source":"Project README","overview":["Experience Lab is an automated, end-to-end deployment accelerator for Azure Data Manager for Energy, with sample data for learning, testing, demos and training.","It creates a Developer-tier instance and includes a simple web UI for basic management (users, legal tags, loading standard sample datasets), so even a non-technical audience can stand up a fully configured, data-loaded instance quickly."],"steps":[{"title":"Deploy the control plane","body":"A Deploy to Azure template creates the control plane in your subscription: storage, a container registry and template specs.","services":["storage","container-registry"]},{"title":"It creates the instance","body":"The control plane creates an Azure Data Manager for Energy developer-tier instance and registers its application in Microsoft Entra ID.","services":["adme"]},{"title":"Sample data loads","body":"Data-load jobs on Container Instances load the TNO sample well and wellbore dataset.","services":["container-instances"]},{"title":"Explore it","body":"A web portal handles basic management (users, legal tags, data loads), with REST scripts, Swagger and Power BI reports to check the data.","services":[]}],"deploy":{"command":"Deploy to Azure (ARM template)","guide":"https://github.com/microsoft/azure-data-manager-for-energy-experience-lab/blob/3e8cc3352c212428fb0d48e13663d49f15152303/control-plane","prerequisites":["Owner, or Contributor and User Access Administrator, on the subscription","Permission to register an application in Microsoft Entra ID","A region that offers Azure Data Manager for Energy"]},"diagrams":[]}'::jsonb, false, 'Cloud Delivery catalog', now(), now()
