select '33333333-3333-4333-8333-100000000003', '11111111-1111-1111-1111-111111111111', 'OSDU on AKS Automatic', 'Runs OSDU on AKS Automatic with Azure-native services (Cosmos DB, Service Bus, Storage and Key Vault), workload identity, Flux GitOps and multiple data partitions.', 'Upstream & Resources', 'Platform teams that operate OSDU themselves', 'Azure-native OSDU on managed Kubernetes, with partitions per business unit', '{osdu,aks-automatic,gitops,multi-partition}'::text[], '[{"name":"Microsoft","email":"","role":"Product team","team":"github.com/Azure"}]'::jsonb, 'validated', 'https://github.com/Azure/osdu-spi-stack', null, '{"source":"Project README and architecture diagram","overview":["The SPI stack runs OSDU on AKS Automatic, where Azure manages the cluster''s nodes, upgrades and Istio, and backs OSDU with Azure-native services instead of in-cluster equivalents wherever it can.","One command provisions everything and hands over to GitOps, and multiple data partitions let one deployment serve several business units."],"steps":[{"title":"One command deploys it","body":"An engineer or CI runs spi up: Bicep provisions the Azure resources and bootstraps GitOps.","services":[]},{"title":"GitOps installs OSDU","body":"Flux controllers in AKS Automatic apply the OSDU sources and configuration from the Git repository.","services":["aks"]},{"title":"Clients call OSDU","body":"API clients reach OSDU over HTTPS through the spi-gateway on the managed Istio ingress.","services":[]},{"title":"Azure services hold the data","body":"OSDU workloads use Cosmos DB (SQL and Gremlin), Service Bus, Storage and Key Vault with a shared OSDU identity; middleware passwords stay in Key Vault.","services":["cosmos","service-bus","storage","key-vault","managed-identity"]},{"title":"Platform services in the cluster","body":"Elasticsearch and Redis serve search and cache; Airflow runs ingestion workflows with Postgres for its metadata; ECK, CloudNativePG, cert-manager and trust-manager manage and certify them.","services":[]}],"diagrams":[{"title":"Architecture","url":"https://raw.githubusercontent.com/Azure/osdu-spi-stack/f5d5d76552a66e755c15ac2ebacdce997184dad0/docs/diagrams/architecture.png","caption":"Ownership boundaries and the paths that serve an OSDU request."}],"deploy":{"command":"spi up","minutes":"45–50 minutes"}}'::jsonb, false, 'Cloud Delivery catalog', now(), now()
